using LightMMORPG.Core;
using UnityEngine;

namespace LightMMORPG.Config
{
    /// <summary>
    /// Global tunables + asset references. Lives at Assets/_Project/Resources/GameConfig.asset (generated by ProjectBuilder)
    /// so referenced shaders/materials are always included in builds.
    /// </summary>
    [CreateAssetMenu(menuName = "LightMMORPG/Game Config", fileName = "GameConfig")]
    public sealed class GameConfig : ScriptableObject
    {
        public const string ResourcePath = "GameConfig";

        [Header("Stats")]
        public float maxHealth = CombatConstants.MaxHealth;
        public float maxEnergy = CombatConstants.MaxEnergy;
        public float energyRegenPerSecond = CombatConstants.EnergyRegenPerSecond;
        public float energyChargePerSecond = CombatConstants.EnergyChargePerSecond;
        public float maxGuard = CombatConstants.MaxGuard;
        public float knockedOutDuration = CombatConstants.KnockedOutDuration;

        [Header("Movement")]
        public float runSpeed = CombatConstants.RunSpeed;
        public float sprintSpeed = CombatConstants.SprintSpeed;
        public float flySpeed = CombatConstants.FlySpeed;
        public float dashSpeed = CombatConstants.DashSpeed;
        public float dashDuration = CombatConstants.DashDuration;
        public float dashCooldown = CombatConstants.DashCooldown;
        public float flashStepDistance = CombatConstants.FlashStepDistance;
        public float flashStepCooldown = CombatConstants.FlashStepCooldown;

        [Header("Melee")]
        public float[] lightComboDamage = (float[])CombatConstants.LightComboDamage.Clone();
        public float comboWindow = CombatConstants.ComboWindow;
        public float heavyDamage = CombatConstants.HeavyDamage;
        public float heavyCooldown = CombatConstants.HeavyCooldown;
        public float meleeHitRadius = CombatConstants.MeleeHitRadius;
        public float meleeHitForwardOffset = CombatConstants.MeleeHitForwardOffset;
        public float lightHitstun = CombatConstants.LightHitstun;
        public float heavyHitstun = CombatConstants.HeavyHitstun;

        [Header("Block")]
        public float blockMoveMultiplier = CombatConstants.BlockMoveMultiplier;
        public float blockDamageReduction = CombatConstants.BlockDamageReduction;
        public float guardBreakStun = CombatConstants.GuardBreakStun;

        [Header("Abilities")]
        public AbilityDefinition energyBlast;
        public AbilityDefinition chargedBeam;
        public AbilityDefinition powerSurge;

        [Header("Materials (filled by ProjectBuilder.BuildArt)")]
        [Tooltip("Body materials, one per player slot (orange, blue, green, purple). Index = player index % length.")]
        public Material[] fighterPaletteMaterials;
        [Tooltip("Default body (= palette 0).")]
        public Material fighterBodyMaterial;
        public Material fighterSkinMaterial;
        public Material fighterAccentMaterial;
        public Material arenaGroundMaterial;
        public Material arenaWallMaterial;
        [Tooltip("Pillars / props.")]
        public Material arenaPropMaterial;
        public Material auraMaterial;
        [Tooltip("Energy Blast projectile.")]
        public Material projectileMaterial;
        public Material beamMaterial;
        public Material impactMaterial;

        [Header("Post-processing (filled by ProjectBuilder.BuildArt)")]
        [Tooltip("Bloom + tonemapping profile for the arena's global Volume.")]
        public UnityEngine.Rendering.VolumeProfile arenaVolumeProfile;

        /// <summary>Body material for a player slot (wraps around the palette list).</summary>
        public Material GetFighterMaterial(int playerIndex)
        {
            if (fighterPaletteMaterials == null || fighterPaletteMaterials.Length == 0) return fighterBodyMaterial;
            int i = ((playerIndex % fighterPaletteMaterials.Length) + fighterPaletteMaterials.Length) % fighterPaletteMaterials.Length;
            return fighterPaletteMaterials[i] != null ? fighterPaletteMaterials[i] : fighterBodyMaterial;
        }

        [Header("VFX / prefabs (filled by later builders)")]
        public GameObject hitVfxPrefab;
        public GameObject projectileVisualPrefab;

        private static GameConfig _cached;

        /// <summary>Loads (and caches) Resources/GameConfig. Logs an error and returns a default instance if missing.</summary>
        public static GameConfig Load()
        {
            if (_cached != null) return _cached;
            _cached = Resources.Load<GameConfig>(ResourcePath);
            if (_cached == null)
            {
                Debug.LogError("GameConfig not found at Resources/" + ResourcePath + ". Run LightMMORPG/Build All.");
                _cached = CreateInstance<GameConfig>();
            }
            return _cached;
        }
    }
}
